// ============================================================
//  ACCOUNTS TO TRACK  <-- EDIT HERE ONLY
//  Add / remove / enable / disable accounts without touching any other node.
//  enabled: false  => account is skipped entirely
// ============================================================

const FETCHERS = {
  Facebook:  'REPLACE_WITH_FACEBOOK_FETCH_WORKFLOW_ID',
  Instagram: 'REPLACE_WITH_INSTAGRAM_FETCH_WORKFLOW_ID',
  TikTok:    'REPLACE_WITH_TIKTOK_FETCH_WORKFLOW_ID',
