  // LinkedIn personal profile: official API can't list member posts (r_member_social is closed), so this one
  // goes through the Apify scraper workflow. account_id = profile URL. Rows come back as platform 'LinkedIn'.
  { platform: 'LinkedIn Profile', channel: 'Brand B', account_id: 'https://www.linkedin.com/in/your-profile/', likes_label: 'Reactions', enabled: true },
  // Threads: official Threads API. account_id = Threads user id. Any channel other than 'Brand A' uses the (Brand B) credential in Social Fetch - Threads.
  { platform: 'Threads', channel: 'Brand A', account_id: 'YOUR_THREADS_USER_ID_A', likes_label: 'Likes', enabled: true },
  { platform: 'Threads', channel: 'Brand B', account_id: 'YOUR_THREADS_USER_ID_B', likes_label: 'Likes', enabled: true },
