// ==================================================
// CONFIG
// ==================================================

const SHOW_LINK_PERFORMANCE = true;

const TRACKED_LINKS = [
  { affiliate_id: 'YTS', url: 'https://short.example.com/syt' },
  { affiliate_id: 'FBS', url: 'https://short.example.com/sfb' },
  { affiliate_id: 'FBCC', url: 'https://short.example.com/ccfb' },
  { affiliate_id: 'IGS', url: 'https://short.example.com/sig' },
  { affiliate_id: 'IGCC', url: 'https://short.example.com/ccig' },
  { affiliate_id: 'TTS', url: 'https://short.example.com/stt' },
  { affiliate_id: 'TTCC', url: 'https://short.example.com/cctt' },
  { affiliate_id: 'TWS', url: 'https://short.example.com/stww' },
  { affiliate_id: 'TWCC', url: 'https://short.example.com/cctw' },
  { affiliate_id: 'TDS', url: 'https://short.example.com/std' },
  { affiliate_id: 'TDCC', url: 'https://short.example.com/cctd' },
  { affiliate_id: 'LIS', url: 'https://short.example.com/sli' },
  { affiliate_id: 'LICC', url: 'https://short.example.com/ccli' },
  { affiliate_id: 'BSCC', url: 'https://short.example.com/ccbs' },
  { affiliate_id: 'FBSGC', url: 'https://short.example.com/fbg' },
  { affiliate_id: 'WASGC', url: 'https://short.example.com/wag' },
];

// Free Masterclass links (example.com/masterclass). Same affiliate IDs as TRACKED_LINKS, so they
// are matched per set (a link is looked up by URL, a platform row by affiliate ID within its set).
const MASTERCLASS_LINKS = [
  { affiliate_id: 'YTS', url: 'https://short.example.com/msyt' },
  { affiliate_id: 'FBS', url: 'https://short.example.com/msfb' },
  { affiliate_id: 'FBCC', url: 'https://short.example.com/mccfb' },
  { affiliate_id: 'IGS', url: 'https://short.example.com/msig' },
  { affiliate_id: 'IGCC', url: 'https://short.example.com/mccig' },
  { affiliate_id: 'TTS', url: 'https://short.example.com/mstt' },
  { affiliate_id: 'TTCC', url: 'https://short.example.com/mcctt' },
  { affiliate_id: 'TWS', url: 'https://short.example.com/mstw' },
  { affiliate_id: 'TWCC', url: 'https://short.example.com/mcctw' },
  { affiliate_id: 'TDS', url: 'https://short.example.com/mstd' },
  { affiliate_id: 'TDCC', url: 'https://short.example.com/mcctd' },
  { affiliate_id: 'LIS', url: 'https://short.example.com/msli' },
  { affiliate_id: 'LICC', url: 'https://short.example.com/mccli' },
  { affiliate_id: 'BSCC', url: 'https://short.example.com/mccbs' },
  { affiliate_id: 'FBSGC', url: 'https://short.example.com/mfbg' },
  { affiliate_id: 'WASGC', url: 'https://short.example.com/mwag' },
];

const LINK_PLATFORMS = [
  { name: 'YouTube', brandA: 'YTS', brandB: null },
  { name: 'Facebook', brandA: 'FBS', brandB: 'FBCC' },
  { name: 'Instagram', brandA: 'IGS', brandB: 'IGCC' },
  { name: 'TikTok', brandA: 'TTS', brandB: 'TTCC' },
  { name: 'Twitter', brandA: 'TWS', brandB: 'TWCC' },
  { name: 'Threads', brandA: 'TDS', brandB: 'TDCC' },
  { name: 'LinkedIn', brandA: 'LIS', brandB: 'LICC' },
  { name: 'BlueSky', brandA: null, brandB: 'BSCC' },
  { name: 'FB Group', brandA: 'FBSGC', brandB: null },
  { name: 'WA Group', brandA: 'WASGC', brandB: null },
];

// ==================================================
// LOAD DATA
// ==================================================

let prevData = $('Load snapshot').first().json.prev;

// Also accept a snapshot stored as a JSON string.
if (typeof prevData === 'string') {
  prevData = prevData.trim() ? JSON.parse(prevData) : null;
}

const prevVideos = (prevData && prevData.videos) || {};
const prevLinks = (prevData && prevData.links) || {};

const isFirstRun = !prevData;
const hasBaseline = !isFirstRun;

const now = Date.now();
const MS_24H = 24 * 60 * 60 * 1000;

const input = $input.all()
  .map(item => item.json)
  .filter(Boolean);

// ==================================================
// HELPERS
// ==================================================

function delta(current, previous, isNew) {
  if (!hasBaseline) return null;
  if (isNew) return null;

  return Math.max(
    0,
    Number(current || 0) - Number(previous || 0)
  );
}

function fmtDelta(value) {
  const n = Number(value || 0);

  return (n >= 0 ? '+' : '') + n.toLocaleString('en-US');
}

function fmtNum(value) {
  return Number(value || 0).toLocaleString('en-US');
}

// Strips characters that would break a Slack code block.
function tableText(value) {
  return String(value == null ? '' : value)
    .replace(/[\r\n\t]+/g, ' ')
    .replace(/`/g, "'");
}

// Slack mrkdwn requires &, <, > to be escaped wherever user-generated
// text (video titles, channel names) is interpolated.
function truncateTitle(value, maxLen) {
  const clean = tableText(value);

  if (clean.length <= maxLen) return clean;

  const cut = clean.slice(0, maxLen);
  const lastSpace = cut.lastIndexOf(' ');
  const safe = lastSpace > maxLen * 0.5 ? cut.slice(0, lastSpace) : cut;

  return safe.trimEnd() + '\u2026';
}

function mrkdwnText(value) {
  return tableText(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function renderTable(
  headers,
  rows,
  emptyMessage = '',
  rightAlignedColumns = [],
  showHeaderDivider = true,
  dividerBeforeRowIndex = null
) {
  const safeHeaders = headers.map(tableText);
  const safeRows = rows.map(row => row.map(tableText));

  const widths = safeHeaders.map((header, index) =>
    Math.max(
      header.length,
      ...safeRows.map(row => (row[index] || '').length)
    )
  );

  function renderLine(row) {
    return row
      .map((value, index) =>
        rightAlignedColumns.includes(index)
          ? value.padStart(widths[index], ' ')
          : value.padEnd(widths[index], ' ')
      )
      .join('  ')
      .trimEnd();
  }

  const divider = widths.map(w => '-'.repeat(w)).join('  ');

  const bodyLines = safeRows.length ? safeRows.map(renderLine) : [emptyMessage];

  if (dividerBeforeRowIndex != null && dividerBeforeRowIndex > 0 && dividerBeforeRowIndex < bodyLines.length) {
    bodyLines.splice(dividerBeforeRowIndex, 0, divider);
  }

  return [
    '```',
    renderLine(safeHeaders),
    ...(showHeaderDivider ? [divider] : []),
    ...bodyLines,
    '```',
  ];
}

function isWithinLastDays(createdAt, days) {
  if (!createdAt) return false;

  const posted = new Date(createdAt).getTime();

  if (Number.isNaN(posted)) return false;

  return posted >= now - days * MS_24H;
}

// ==================================================
// CALCULATE SOCIAL POST CHANGES
// ==================================================

const seenRowKeys = new Set();

const rows = input
  .filter(row => row.kind !== 'link' && row.id)
  .filter(row => {
    const key = `${row.platform}|${row.channel}|${row.id}`;

    if (seenRowKeys.has(key)) return false;
    seenRowKeys.add(key);
    return true;
  })
  .map(row => ({ ...row }));

rows.forEach(row => {
  const key = `${row.platform}|${row.channel}|${row.id}`;
  const previous = prevVideos[key];
  const isNew = hasBaseline && !previous;

  row.viewsDelta = delta(row.views, previous && previous.views, isNew);
  row.likesDelta = delta(row.likes, previous && previous.likes, isNew);
  row.commentsDelta = delta(row.comments, previous && previous.comments, isNew);
  row.sharesDelta = delta(row.shares, previous && previous.shares, isNew);
  row.isNew = isNew;
});

// ==================================================
// GROUP AND RANK POSTS
// ==================================================

const grouped = Object.create(null);

rows.forEach(row => {
  const group = `${row.platform}|${row.channel}`;

  if (!grouped[group]) grouped[group] = [];

  grouped[group].push(row);
});

// Per channel: every post from the last 7 days (most-viewed first, for
// "Top performing"), and every post from the last 24h (most-viewed first,
// for "New posts"). Both are time-window based, not delta-since-last-run.
const changedByGroup = Object.create(null);
const new24hByGroup = Object.create(null);

Object.keys(grouped).forEach(group => {
  changedByGroup[group] = grouped[group]
    .filter(row => isWithinLastDays(row.created_at, 7))
    .sort((a, b) => (b.views || 0) - (a.views || 0));

  new24hByGroup[group] = grouped[group]
    .filter(row => isWithinLastDays(row.created_at, 1))
    .sort((a, b) => (b.views || 0) - (a.views || 0));
});



// ==================================================
// PREPARE BITLY DATA
// ==================================================

// Expected input from the Bitly sub-workflow:
// {
//   kind: 'link',
//   url: 'https://short.example.com/syt',
//   clicks: 120,
//   source: 'bitly'
// }
//
// clicks is Bitly's trailing-1-day count (~last 24h), not a lifetime total.
// The delta below is then simply today's count vs the last run's count.

function clickCount(value) {
  if (value == null || (typeof value === 'string' && value.trim() === '')) {
    return null;
  }

  if (!['number', 'string'].includes(typeof value)) {
    return null;
  }

  const n = Number(value);

  return Number.isFinite(n) && n >= 0 ? n : null;
}

const linkInput = new Map(
  input
    .filter(row => row.kind === 'link' && row.url)
    .map(row => [row.url, row])
);

const links = Object.create(null);

function trackLinks(configs) {
  return configs.map(config => {
    const current = linkInput.get(config.url);

    const clicks = clickCount(current && current.clicks);
    const source = String((current && current.source) || '');

    const previous = prevLinks[config.url];

    const previousClicks =
      previous && (previous.source || '') === source
        ? clickCount(previous.clicks)
        : null;

    const clicksDelta =
      clicks != null && previousClicks != null
        ? clicks - previousClicks
        : null;

    links[config.url] = { clicks, source };

    return {
      ...config,
      clicks,
      clicksDelta,
      status: clicks == null ? 'unavailable' : 'available',
    };
  });
}

const linkTracking = trackLinks(TRACKED_LINKS);
const masterclassTracking = trackLinks(MASTERCLASS_LINKS);

// ==================================================
// BUILD REPORT (Slack Block Kit)
// ==================================================
// Block Kit instead of a monospace code-block dump: Slack renders ``` tables
// as fixed-width text that doesn't wrap, so wide tables (rank + title + 4
// metric columns) get clipped on anything but a wide desktop pane. Sections
// and fields reflow naturally instead.

const blocks = [];

const reportDateLabel = new Date(now).toLocaleDateString('en-US', {
  weekday: 'short',
  month: 'short',
  day: 'numeric',
  timeZone: 'Asia/Singapore',
});

blocks.push({
  type: 'header',
  text: { type: 'plain_text', text: '📊 Social Daily Report', emoji: true },
});

blocks.push({
  type: 'context',
  elements: [{ type: 'mrkdwn', text: `${reportDateLabel} · vs. previous run` }],
});

const totalViews = rows.reduce((sum, row) => sum + Number(row.views || 0), 0);
const totalViewsDelta = rows.reduce((sum, row) => sum + Number(row.viewsDelta || 0), 0);
const totalNewPosts = rows.filter(row => isWithinLastDays(row.created_at, 1)).length;

const availableClicks = linkTracking.filter(link => link.clicks != null);
const totalLinkClicks = availableClicks.length
  ? availableClicks.reduce((sum, link) => sum + link.clicks, 0)
  : null;

// Single pipe-separated summary line.
blocks.push({
  type: 'section',
  text: {
    type: 'mrkdwn',
    text:
      `*Total views:* ${fmtNum(totalViews)} (${fmtDelta(totalViewsDelta)}) | ` +
      `*New posts:* ${totalNewPosts} | ` +
      `*Link clicks (24h):* ${totalLinkClicks == null ? 'N/A' : fmtNum(totalLinkClicks)}`,
  },
});

blocks.push({ type: 'divider' });

// Only annotate with a change when one is actually known and non-zero.
function cell(value, delta) {
  // null = platform doesn't expose this metric (e.g. LinkedIn personal-profile views)
  if (value == null) return 'N/A';

  const v = fmtNum(value);

  return (delta == null || delta === 0) ? v : `${v} (${fmtDelta(delta)})`;
}

function formatDateAdded(createdAt) {
  if (!createdAt) return '\u2014';

  const d = new Date(createdAt);

  if (Number.isNaN(d.getTime())) return '\u2014';

  return d.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    timeZone: 'Asia/Singapore',
  });
}

// Merges "new in last 24h" and "top performing in last 7 days" into one
// deduped list (a post can legitimately qualify for both), sorted by views.
function mergePosts(freshRows, topRows) {
  const byId = new Map();

  [...freshRows, ...topRows].forEach(row => {
    if (!byId.has(row.id)) byId.set(row.id, row);
  });

  return [...byId.values()].sort((a, b) => (b.views || 0) - (a.views || 0));
}

const STATS_HEADERS = ['#', 'Date Added', 'Post', 'Type', 'Total Views', 'Reactions', 'Comments', 'Shares'];
const STATS_RIGHT_ALIGNED = [4, 5, 6, 7];

function statsRowCells(row, index) {
  return [
    `${index + 1}`,
    formatDateAdded(row.created_at),
    tableText(truncateTitle(row.title, 32)),
    tableText(row.type || '\u2014'),
    cell(row.views, row.viewsDelta),
    cell(row.likes, row.likesDelta),
    cell(row.comments, row.commentsDelta),
    cell(row.shares, row.sharesDelta),
  ];
}

// Renders with EXTERNALLY supplied column widths instead of auto-sizing
// from its own rows, so every channel's table lines up identically
// instead of each one sizing independently to its own numbers.
// Clearbit's public Logo API was deprecated (HubSpot acquisition) --
// switched to Google's favicon service, which is reliably public.
const PLATFORM_LOGOS = {
  Facebook: 'https://www.google.com/s2/favicons?domain=facebook.com&sz=128',
  Instagram: 'https://www.google.com/s2/favicons?domain=instagram.com&sz=128',
  X: 'https://www.google.com/s2/favicons?domain=x.com&sz=128',
  TikTok: 'https://www.google.com/s2/favicons?domain=tiktok.com&sz=128',
  YouTube: 'https://www.google.com/s2/favicons?domain=youtube.com&sz=128',
  LinkedIn: 'https://www.google.com/s2/favicons?domain=linkedin.com&sz=128',
  Threads: 'https://www.google.com/s2/favicons?domain=threads.com&sz=128',
};

function renderFixedWidthTable(headers, rowsCells, emptyMessage, rightAlignedColumns, widths) {
  function renderLine(cells) {
    return cells
      .map((value, index) =>
        rightAlignedColumns.includes(index)
          ? String(value).padStart(widths[index], ' ')
          : String(value).padEnd(widths[index], ' ')
      )
      .join('  ')
      .trimEnd();
  }

  return [
    '```',
    renderLine(headers),
    ...(rowsCells.length ? rowsCells.map(renderLine) : [emptyMessage]),
    '```',
  ];
}

// Account-first layout: each account's own section lists every platform it
// has data for underneath it. Channel names here mirror the main workflow's
// Accounts config -- keep both in sync if a channel name ever changes.
const ACCOUNTS = [
  {
    name: 'Dr. Brand B',
    channels: {
      Facebook: 'DR Brand B',
      Instagram: '@brand_b',
      X: 'Brand B',
      TikTok: 'Brand B',
      LinkedIn: 'Brand B',
      Threads: 'Brand B',
    },
  },
  {
    name: 'Brand A',
    channels: {
      Facebook: 'Brand A',
      Instagram: '@brand_a',
      X: 'Brand A',
      TikTok: 'Brand A',
      YouTube: 'Brand A',
      LinkedIn: 'Brand A',
      Threads: 'Brand A',
    },
  },
];

const PLATFORM_ORDER = ['Facebook', 'Instagram', 'X', 'TikTok', 'YouTube', 'LinkedIn', 'Threads'];

// Pass 1: gather every channel's rows first, so column widths can be
// computed once globally -- otherwise each table auto-sizes independently
// and numbers don't line up between channels (e.g. Facebook's "612" vs
// Instagram's "9,509 (+4)").
const accountSections = ACCOUNTS.map(account => {
  const platforms = PLATFORM_ORDER
    .map(platform => {
      const channel = account.channels[platform];
      const group = channel && `${platform}|${channel}`;

      if (!group || !grouped[group]) return null;

      const fresh = (new24hByGroup[group] || []).slice(0, 3);
      const top3 = (changedByGroup[group] || []).slice(0, 3);
      const merged = mergePosts(fresh, top3);

      return {
        platform,
        rowsCells: merged.map(statsRowCells),
      };
    })
    .filter(Boolean);

  return { name: account.name, platforms };
}).filter(section => section.platforms.length);

const allStatsRows = accountSections.flatMap(section =>
  section.platforms.flatMap(p => p.rowsCells)
);

const statsWidths = STATS_HEADERS.map((label, index) => {
  const dataLen = allStatsRows.reduce(
    (max, row) => Math.max(max, (row[index] || '').length),
    0
  );

  return Math.max(label.length, dataLen);
});

// Pass 2: emit blocks using the globally-computed widths.
accountSections.forEach(section => {
  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `*${section.name}*` },
  });

  section.platforms.forEach(({ platform, rowsCells }) => {
    blocks.push({
      type: 'context',
      elements: [
        { type: 'image', image_url: PLATFORM_LOGOS[platform], alt_text: platform },
        { type: 'mrkdwn', text: `*${platform}*` },
      ],
    });

    const body =
      `_New in last 24h + top performing (last 7 days):_\n` +
      renderFixedWidthTable(
        STATS_HEADERS,
        rowsCells,
        '(nothing to show)',
        STATS_RIGHT_ALIGNED,
        statsWidths
      ).join('\n');

    blocks.push({ type: 'section', text: { type: 'mrkdwn', text: body } });
  });

  blocks.push({ type: 'divider' });
});

function addLinkTable(title, tracking) {
  function formatClicks(clicks, change) {
    if (clicks == null) return 'N/A';

    const total = clicks.toLocaleString('en-US');

    // Only annotate with a change when one is actually known and non-zero --
    // no baseline yet (first run) or an unchanged count both just show the total.
    if (change == null || change === 0) return total;

    return `${total} (${fmtDelta(change)})`;
  }

  const linksByAffiliate = new Map(
    tracking.map(link => [link.affiliate_id, link])
  );

  function accountCell(affiliateId) {
    if (!affiliateId) return '—';

    const link = linksByAffiliate.get(affiliateId);

    return formatClicks(
      link ? link.clicks : null,
      link ? link.clicksDelta : null
    );
  }

  const tableRows = LINK_PLATFORMS.map((platform, index) => {
    const assignedIds = [platform.brandA, platform.brandB].filter(Boolean);
    const assignedLinks = assignedIds.map(id => linksByAffiliate.get(id));

    const hasAllCounts = assignedLinks.every(link => link && link.clicks != null);
    const hasAllChanges = assignedLinks.every(link => link && link.clicksDelta != null);

    const totalClicks = hasAllCounts
      ? assignedLinks.reduce((sum, link) => sum + link.clicks, 0)
      : null;
    const totalChange = hasAllChanges
      ? assignedLinks.reduce((sum, link) => sum + link.clicksDelta, 0)
      : null;

    return [
      `${index + 1}`,
      platform.name,
      accountCell(platform.brandA),
      accountCell(platform.brandB),
      formatClicks(totalClicks, totalChange),
    ];
  });

  // Sum across every available link (unavailable/unassigned ones are
  // skipped rather than treated as zero, so a not-yet-configured platform
  // doesn't silently drag the grand total down).
  function sumAvailable(links, field) {
    const available = links.filter(link => link && link[field] != null);

    return available.length
      ? available.reduce((sum, link) => sum + link[field], 0)
      : null;
  }

  const brandALinks = LINK_PLATFORMS
    .map(platform => platform.brandA && linksByAffiliate.get(platform.brandA))
    .filter(Boolean);
  const brandBLinks = LINK_PLATFORMS
    .map(platform => platform.brandB && linksByAffiliate.get(platform.brandB))
    .filter(Boolean);

  tableRows.push([
    '\u2014',
    'Total',
    formatClicks(sumAvailable(brandALinks, 'clicks'), sumAvailable(brandALinks, 'clicksDelta')),
    formatClicks(sumAvailable(brandBLinks, 'clicks'), sumAvailable(brandBLinks, 'clicksDelta')),
    formatClicks(sumAvailable(tracking, 'clicks'), sumAvailable(tracking, 'clicksDelta')),
  ]);

  blocks.push({
    type: 'section',
    text: { type: 'mrkdwn', text: `*${title}*` },
  });

  blocks.push({
    type: 'section',
    text: {
      type: 'mrkdwn',
      text: renderTable(
        ['#', 'Platform', 'Brand A', 'Brand B', 'Total'],
        tableRows,
        '',
        [2, 3, 4],
        false,
        tableRows.length - 1
      ).join('\n'),
    },
  });
}

if (SHOW_LINK_PERFORMANCE) {
  addLinkTable('🔗 Link performance (example.com/webinars)', linkTracking);
  addLinkTable('🎓 Free Masterclass (example.com/masterclass)', masterclassTracking);
}

// ==================================================
// SNAPSHOT AND OUTPUT
// ==================================================

const videos = Object.create(null);

rows.forEach(row => {
  const key = `${row.platform}|${row.channel}|${row.id}`;

  videos[key] = {
    views: row.views,
    likes: row.likes,
    comments: row.comments,
    shares: row.shares,
    title: row.title,
  };
});

const snapshot = {
  date: new Date(now).toISOString().slice(0, 10),
  videos,
  links,
};

// Slack's chat.postMessage still wants a plain-text `text` as a notification
// fallback even when sending Block Kit `blocks`.
const fallbackText =
  `Social Daily Report: ${fmtNum(totalViews)} views (${fmtDelta(totalViewsDelta)}), ` +
  `${totalNewPosts} new post${totalNewPosts === 1 ? '' : 's'}.`;

return [
  {
    json: {
      text: fallbackText,
      blocks,
      blocksJson: JSON.stringify({ blocks }),
      videoCount: rows.length,
      snapshot,
      isFirstRun,
      linkTracking,
      masterclassTracking,
    },
  },
];
